export function characterRomanizedNameFor(category: string, folderName: string): string {
  if (
    category !== 'character_story'
    && category !== 'costume_story'
    && category !== 'general_voice'
  ) {
    return '';
  }
  const folderId = folderName.match(/^(\d+)/)?.[1];
  return folderId ? CHARACTER_ROMAJI_BY_FOLDER_ID[folderId] ?? '' : '';
}
